import {createClient} from 'npm:@supabase/supabase-js@2.112.4';

const keys=JSON.parse(Deno.env.get('SUPABASE_SECRET_KEYS')||'{}');
const db=createClient(Deno.env.get('SUPABASE_URL')!,keys.default||Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!,{auth:{persistSession:false,autoRefreshToken:false}});
const base=Deno.env.get('SUPABASE_URL')!;
const IMMOMIO=`${base}/functions/v1/immomio-account`;
const STATUS_SYNC=`${base}/functions/v1/notification-dispatcher`;

async function secret(name:string){const {data,error}=await db.rpc('get_bot_secret',{secret_name:name});if(error||!data)throw Error('configuration_unavailable');return String(data);}
const clean=(v:any,max=200)=>String(v??'').replace(/[\u0000-\u001f\u007f]/g,' ').replace(/\s+/g,' ').trim().slice(0,max);
async function syncListingStatus(userId:string,listingId:string){try{const internal=await secret('internal_worker_secret');await fetch(STATUS_SYNC,{method:'POST',headers:{'content-type':'application/json','x-internal-secret':internal},body:JSON.stringify({action:'sync_application_status',userId,listingId}),signal:AbortSignal.timeout(15000)});}catch{}}
async function immomio(action:string,userId:string,listingId:string,extra:Record<string,unknown>={}){const internal=await secret('internal_worker_secret');const r=await fetch(IMMOMIO,{method:'POST',headers:{'content-type':'application/json','x-internal-secret':internal},body:JSON.stringify({action,userId,listingId,...extra}),signal:AbortSignal.timeout(45000)});const data=await r.json().catch(()=>null);if(!r.ok)throw Error(data?.error||`immomio_worker_${r.status}`);return data;}
async function immomioRequestStarted(applicationId:string){const {data,error}=await db.rpc('immomio_application_request_started',{p_application:applicationId});if(error)return null;return data===true;}

function immomioDocumentState(result:any){
 const transfer=result?.documentTransfer;
 const documentFailure=/^(document_|application_documents_)/.test(String(result?.error||''));
 if(!transfer||typeof transfer!=='object')return documentFailure?{document_result:'transfer_failed'}:{};
 const counts=['selected','uploaded','reused'] as const;
 if(!counts.every(key=>Number.isSafeInteger(transfer[key])&&transfer[key]>=0))return documentFailure?{document_result:'transfer_failed'}:{};
 const verified=transfer.verified===true&&transfer.uploaded+transfer.reused===transfer.selected;
 const documentTransfer={selected:transfer.selected,uploaded:transfer.uploaded,reused:transfer.reused,verified,
  ...(Number.isSafeInteger(transfer.removed)&&transfer.removed>=0?{removed:transfer.removed}:{})};
 return{documentTransfer,document_result:documentFailure||!verified?'transfer_failed':transfer.selected>0?'native_uploaded':'not_provided'};
}

async function processOne(){
 const {data:claimed,error:claimError}=await db.rpc('claim_immomio_application');
 if(claimError)throw Error('application_claim_failed');
 if(!claimed?.length)return {status:'idle'};
 const application=claimed[0];
 let started=false;
 const patch=async(value:any)=>{const {data,error}=await db.from('applications').update(value).eq('id',application.id).eq('lease_token',application.lease_token).select('id');if(error||!data?.length)throw Error('application_lease_lost');};
 try{
  const [{data:user,error:userError},{data:listing,error:listingError},{data:connection,error:connectionError}]=await Promise.all([
   db.from('bot_users').select('id,chat_id,is_active,auto_apply_enabled').eq('id',application.user_id).single(),
   db.from('listings').select('id,source_id,title,is_active,canonical_url,raw').eq('id',application.listing_id).single(),
   db.from('platform_connections').select('status').eq('user_id',application.user_id).eq('provider','immomio').maybeSingle()
  ]);
  if(userError||listingError||connectionError)throw Error('application_read_failed');

  if(!user.auto_apply_enabled||!user.is_active||!listing.is_active){await patch({status:'failed',last_error:'not_eligible',wait_reason:null,provider_state:{provider:'immomio'},lease_until:null});await syncListingStatus(String(application.user_id),String(application.listing_id));return {status:'failed',error:'not_eligible'};}
  if(connection?.status!=='connected'){await patch({status:'failed',last_error:'provider_disabled',provider_state:{provider:'immomio'},lease_until:null});await syncListingStatus(String(application.user_id),String(application.listing_id));return {status:'failed',provider:'immomio',error:'provider_disabled'};}

  const probe=await immomio('probe',String(user.id),String(listing.id));
  if(probe?.ready!==true){const error=clean(probe?.error||'provider_contract_unverified',120),providerState={provider:'immomio',alreadyApplied:probe?.alreadyApplied===true,applicationId:probe?.applicationId||null,customQuestionCount:probe?.customQuestionCount||0,hierarchicalQuestionCount:probe?.hierarchicalQuestionCount||0};await patch({status:'manual_required',last_error:error,provider_state:providerState,lease_until:null});await syncListingStatus(String(application.user_id),String(application.listing_id));return {status:'manual_required',provider:'immomio',error};}

  if(!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(String(probe.sourceIdentifier||'')))throw Error('application_target_unverified');
  const {data:authorized,error:authError}=await db.rpc('authorize_immomio_application_send',{p_id:application.id,p_token:application.lease_token,p_source_identifier:probe.sourceIdentifier});
  if(authError){started=true;throw Error('authorization_unconfirmed');}
  if(authorized!==true){
   const {data:current}=await db.from('applications').select('status,last_error,wait_reason,next_attempt_at').eq('id',application.id).eq('lease_token',application.lease_token).maybeSingle();
   if(current&&['failed','manual_required'].includes(current.status)){await syncListingStatus(String(application.user_id),String(application.listing_id));return {status:current.status,provider:'immomio',error:current.last_error};}
   if(current?.status==='pending'&&current?.wait_reason){await patch({lease_until:null});await syncListingStatus(String(application.user_id),String(application.listing_id));return {status:'deferred',provider:'immomio',error:current.wait_reason};}
   await patch({status:'failed',last_error:'send_not_authorized',provider_state:{provider:'immomio'},lease_until:null});await syncListingStatus(String(application.user_id),String(application.listing_id));return {status:'failed',provider:'immomio',error:'send_not_authorized'};
  }
  started=true;

  const result=await immomio('send_authorized',String(user.id),String(listing.id),{applicationId:application.id,leaseToken:application.lease_token,sourceIdentifier:probe.sourceIdentifier});
  const status=['sent','failed','manual_required'].includes(String(result?.status))?String(result.status):'manual_required';
  const error=result?.error?clean(result.error,120):null,providerState={provider:'immomio',applicationId:result?.applicationId||null,providerStatus:result?.providerStatus||null,followUpRequired:result?.followUpRequired||null,hasQuestions:result?.hasQuestions??null,hasUnansweredQuestions:result?.hasUnansweredQuestions??null,smsVerificationRequired:result?.smsVerificationRequired??false,hierarchicalQuestionCount:result?.hierarchicalQuestionCount||0,...immomioDocumentState(result)};
  await patch({status,last_error:error,provider_state:providerState,...(status==='sent'?{sent_at:new Date().toISOString()}:{}),lease_until:null});
  await syncListingStatus(String(application.user_id),String(application.listing_id));
  return {status,provider:'immomio',error,documentResult:providerState.document_result||null};
 }catch(error:any){
  const code=String(error?.message||'application_preparation_failed');
  const attempts=Number(application.attempts||0);
  const requestStarted=started?await immomioRequestStarted(String(application.id)):false;
  const transientBeforeAuthorization=!started&&['temporary_network_error','TimeoutError','immomio_operation_failed'].includes(error?.name==='TimeoutError'?'TimeoutError':code);
  const safePreSubmitRetry=started&&requestStarted===false;
  const retry=(transientBeforeAuthorization||safePreSubmitRetry)&&attempts<3;
  const terminalStatus=(started&&requestStarted!==false)?'manual_required':retry?'pending':'failed';
  const finalError=terminalStatus==='manual_required'?'submission_unconfirmed':retry?'temporary_network_error':clean(code,120);
  const retryPatch=retry?{submission_started_at:null,next_attempt_at:new Date(Date.now()+60000*Math.max(1,attempts+1)).toISOString(),wait_reason:null}:{};
  await patch({status:terminalStatus,last_error:finalError,provider_state:{...application.provider_state,provider:'immomio',requestStarted},...(retry&&!started?{attempts:attempts+1}:{}),...retryPatch,lease_until:null});
  await syncListingStatus(String(application.user_id),String(application.listing_id));
  return {status:terminalStatus,provider:'immomio',error:finalError,requestStarted};
 }
}

Deno.serve(async req=>{try{if(req.method!=='POST')return new Response('method not allowed',{status:405});if(req.headers.get('x-internal-secret')!==await secret('internal_worker_secret'))return new Response('unauthorized',{status:401});const body=await req.json().catch(()=>({}));if(body.action==='health')return Response.json({ok:true,mode:'immomio-auto-application-worker',applicationTargets:'central-db-resolver',sendAuthorization:'single-use-object-lease'});if(body.action!=='process')return Response.json({error:'invalid_action'},{status:400});return Response.json(await processOne());}catch(error:any){return Response.json({error:clean(error?.message||'worker_failed',120)},{status:503});}});

import {claimPlatformConnectFlow,completePlatformConnectFlow} from '../_shared/platform-auth-flow.ts';
import {createClient} from 'npm:@supabase/supabase-js@2.112.4';

const keys=JSON.parse(Deno.env.get('SUPABASE_SECRET_KEYS')||'{}');
const db=createClient(Deno.env.get('SUPABASE_URL')!,keys.default||Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!,{auth:{persistSession:false,autoRefreshToken:false}});
const GQL='https://gql-ps.immomio.com/tenant/graphql';
const TENANT='https://tenant.immomio.com';
const REDIRECT='https://tenant.immomio.com/robots.txt';
const SSO_HOST='sso.immomio.com';
const REALM='immomio';
const CLIENT_ID='immomio-oidc-web';
const LOGIN_METHOD='DEFAULT';
const PKCE_ALPHABET='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
const HEADERS={'content-type':'application/json','accept':'application/json','origin':TENANT,'referer':`${TENANT}/`,'user-agent':'TraumWohnungHamburg/1.0'};
const SSO_QUERY=`query sso($email: String, $redirectUri: String!, $loginMethod: String) { sso(input: { email: $email redirectUri: $redirectUri loginMethod: $loginMethod }) { baseUrl clientId realm } }`;
const enc=new TextEncoder();
const b64url=(bytes:Uint8Array)=>{let s='';for(const b of bytes)s+=String.fromCharCode(b);return btoa(s).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'')};
const b64=(bytes:Uint8Array)=>{let s='';for(const b of bytes)s+=String.fromCharCode(b);return btoa(s)};
const unb64=(v:string)=>Uint8Array.from(atob(v),c=>c.charCodeAt(0));
const randomState=()=>b64url(crypto.getRandomValues(new Uint8Array(32))).slice(0,40);
const randomVerifier=()=>{const bytes=crypto.getRandomValues(new Uint8Array(96));let s='';for(const b of bytes)s+=PKCE_ALPHABET[b%PKCE_ALPHABET.length];return s};
const validEmail=(v:any)=>{const s=String(v||'').trim().toLowerCase();return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(s)?s:null};
const safeDiag=(v:any,max=80)=>String(v||'').replace(/[^a-zA-Z0-9 _.:/-]/g,'').trim().slice(0,max);
const uuid=(v:any)=>{const s=String(v||'');if(!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(s))throw Error('invalid_user');return s};

async function secret(name:string){const {data,error}=await db.rpc('get_bot_secret',{secret_name:name});if(error||!data)throw Error('configuration_unavailable');return String(data)}
async function eligible(userId:string){const {data,error}=await db.rpc('application_user_eligible',{p_user:userId});if(error||data!==true)throw Error('premium_required')}
async function challenge(v:string){return b64url(new Uint8Array(await crypto.subtle.digest('SHA-256',enc.encode(v))))}
async function rawGraphql(query:string,variables:any){const response=await fetch(GQL,{method:'POST',headers:HEADERS,body:JSON.stringify({query,variables}),signal:AbortSignal.timeout(25000)}),body=await response.json().catch(()=>null);return{response,body}}
async function resolveSso(email:string){const r=await rawGraphql(SSO_QUERY,{email,redirectUri:REDIRECT,loginMethod:LOGIN_METHOD});const s=r.body?.data?.sso;if(!r.response.ok||r.body?.errors?.length||!s)throw Error('immomio_sso_failed');let u:URL;try{u=new URL(String(s.baseUrl||''))}catch{throw Error('immomio_sso_contract_changed')}if(u.protocol!=='https:'||u.hostname!==SSO_HOST||String(s.realm)!==REALM||String(s.clientId)!==CLIENT_ID)throw Error('immomio_sso_contract_changed');return{baseUrl:`https://${SSO_HOST}/auth`,realm:REALM,clientId:CLIENT_ID}}
async function tokenRequest(cfg:any,payload:Record<string,string>){const response=await fetch(`${cfg.baseUrl}/realms/${encodeURIComponent(cfg.realm)}/protocol/openid-connect/token`,{method:'POST',headers:{'content-type':'application/x-www-form-urlencoded','accept':'application/json'},body:new URLSearchParams({...payload,client_id:cfg.clientId}),signal:AbortSignal.timeout(25000)}),token=await response.json().catch(()=>null);return{response,token}}
function decodeEmail(token:any){try{const p=String(token||'').split('.')[1];if(!p)return null;return validEmail(JSON.parse(atob(p.replace(/-/g,'+').replace(/_/g,'/').padEnd(Math.ceil(p.length/4)*4,'=')))?.email)}catch{return null}}
async function keyMaterial(){const raw=unb64(await secret('application_credential_key_v1'));if(raw.length!==32)throw Error('credential_key_invalid');return crypto.subtle.importKey('raw',raw,{name:'AES-GCM'},false,['encrypt'])}
async function encrypt(userId:string,value:any){const iv=crypto.getRandomValues(new Uint8Array(12)),key=await keyMaterial(),aad=enc.encode(`${userId}:immomio:v1`),plain=enc.encode(JSON.stringify(value)),cipher=new Uint8Array(await crypto.subtle.encrypt({name:'AES-GCM',iv,additionalData:aad},key,plain));return{credential_ciphertext:b64(cipher),credential_iv:b64(iv),key_version:1}}
async function profileEmail(userId:string){const {data,error}=await db.from('applicant_profiles').select('email').eq('user_id',userId).maybeSingle();const email=validEmail(data?.email);if(error||!email)throw Error('immomio_email_required');return email}
async function markPending(userId:string,email:string){const {error}=await db.from('platform_connections').upsert({user_id:userId,provider:'immomio',status:'pending',account_hint:email,last_error:null,updated_at:new Date().toISOString()},{onConflict:'user_id,provider'});if(error)throw Error('connection_update_failed')}

async function begin(userId:string){
 const email=await profileEmail(userId),cfg=await resolveSso(email);
 await db.from('platform_auth_flows').delete().eq('user_id',userId).eq('provider','immomio').is('consumed_at',null);
 const verifier=randomVerifier(),state=randomState(),cc=await challenge(verifier),{error}=await db.from('platform_auth_flows').insert({user_id:userId,provider:'immomio',state,code_verifier:verifier});if(error)throw Error('auth_flow_create_failed');
 await markPending(userId,email);
 const url=new URL(`${cfg.baseUrl}/realms/${encodeURIComponent(cfg.realm)}/protocol/openid-connect/auth`);
 const params={client_id:cfg.clientId,redirect_uri:REDIRECT,response_type:'code',response_mode:'query',scope:'openid profile email',state,code_challenge:cc,code_challenge_method:'S256',login_hint:email,prompt:'login'};
 for(const[k,v]of Object.entries(params))url.searchParams.set(k,String(v));
 return{status:'login',url:url.href,transport:'telegram-share-bridge',redirectUri:REDIRECT,reuseExistingSession:false,completionMode:'token-exchange-then-save',expiresInSeconds:600}
}

function callback(v:string){let u:URL;try{u=new URL(String(v||'').trim())}catch{throw Error('invalid_callback_url')}if(u.protocol!=='https:'||u.hostname!=='tenant.immomio.com'||u.port||u.username||u.password||u.pathname!=='/robots.txt')throw Error('invalid_callback_url');const state=u.searchParams.get('state'),code=u.searchParams.get('code');if(!state||!code)throw Error('invalid_callback_url');return{state,code}}
async function complete(userId:string,callbackUrl:string){
 const {state,code}=callback(callbackUrl),{data:flow,error}=await db.from('platform_auth_flows').select('*').eq('user_id',userId).eq('provider','immomio').eq('state',state).is('consumed_at',null).gt('expires_at',new Date().toISOString()).maybeSingle();if(error||!flow)throw Error('auth_flow_expired');
 await claimPlatformConnectFlow(db,flow);
 const email=await profileEmail(userId),cfg=await resolveSso(email),{response,token}=await tokenRequest(cfg,{grant_type:'authorization_code',code,redirect_uri:REDIRECT,code_verifier:String(flow.code_verifier||'')});
 if(!response.ok||!token?.access_token||!token?.refresh_token){const detail=`token_exchange_failed:${response.status}:${safeDiag(token?.error)}:${safeDiag(token?.error_description)}`.slice(0,120);await db.from('platform_connections').upsert({user_id:userId,provider:'immomio',status:'needs_login',last_error:detail,updated_at:new Date().toISOString()},{onConflict:'user_id,provider'});throw Error('token_exchange_failed')}
 const expiresAt=new Date(Date.now()+Math.max(60,Number(token.expires_in||300))*1000).toISOString();
 const hint=decodeEmail(token.id_token)||email;
 const encrypted=await encrypt(userId,{access_token:String(token.access_token),refresh_token:String(token.refresh_token),expires_at:expiresAt,base_url:cfg.baseUrl,realm:cfg.realm,client_id:cfg.clientId,redirect_uri:REDIRECT});
 const now=new Date().toISOString();
 await completePlatformConnectFlow(db,flow,{...encrypted,account_hint:hint,expires_at:expiresAt});
 return{status:'connected',authenticated:true,accountHint:hint,verificationDeferred:true}
}

async function latestCallback(userId:string){
 const {data:user,error:userError}=await db.from('bot_users').select('telegram_user_id').eq('id',userId).maybeSingle();if(userError||!user?.telegram_user_id)throw Error('callback_not_found');
 const {data:flow,error:flowError}=await db.from('platform_auth_flows').select('state').eq('user_id',userId).eq('provider','immomio').is('consumed_at',null).gt('expires_at',new Date().toISOString()).order('created_at',{ascending:false}).limit(1).maybeSingle();if(flowError||!flow?.state)throw Error('auth_flow_expired');
 const {data:events,error:eventError}=await db.from('bot_events').select('payload,created_at').eq('telegram_user_id',user.telegram_user_id).order('created_at',{ascending:false}).limit(20);if(eventError||!Array.isArray(events))throw Error('callback_not_found');
 for(const event of events){const text=String(event?.payload?.message?.text||'').trim();if(!text.startsWith(`${REDIRECT}?`))continue;try{const parsed=callback(text);if(parsed.state===String(flow.state))return text}catch{}}
 throw Error('callback_not_found')
}

Deno.serve(async req=>{try{
 if(req.method!=='POST')return new Response('method not allowed',{status:405});
 if(req.headers.get('x-internal-secret')!==await secret('internal_worker_secret'))return new Response('unauthorized',{status:401});
 const body=await req.json();if(body.action==='health')return Response.json({ok:true,mode:'immomio-pkce-share-robots-kleinanzeigen-style',redirectUri:REDIRECT,reuseExistingSession:false,completionMode:'token-exchange-then-save'});
 const userId=uuid(body.userId);await eligible(userId);
 if(body.action==='login')return Response.json(await begin(userId));
 if(body.action==='complete_login')return Response.json(await complete(userId,String(body.callbackUrl||'')));
 if(body.action==='complete_latest')return Response.json(await complete(userId,await latestCallback(userId)));
 throw Error('invalid_action')
}catch(e:any){const safe=new Set(['configuration_unavailable','premium_required','invalid_user','invalid_action','immomio_email_required','immomio_sso_failed','immomio_sso_contract_changed','auth_flow_create_failed','invalid_callback_url','auth_flow_expired','token_exchange_failed','connection_save_failed','connection_update_failed','credential_key_invalid','callback_not_found']);return Response.json({error:safe.has(e?.message)?e.message:'immomio_auth_bridge_failed'},{status:503})}});

// Keep provider calls outside SQL; reserve and persist their successful result once.
export async function claimPlatformConnectFlow(db:any,flow:any){
 const {data,error}=await db.rpc('claim_platform_connect_flow',{
  p_flow:flow.id,p_user:flow.user_id,p_provider:flow.provider
 });
 if(error||typeof data!=='string'||!data)throw Error(error?.message||'auth_flow_expired');
 flow.completionClaim=data;
 return data;
}
export async function completePlatformConnectFlow(db:any,flow:any,connection:any){
 if(!flow.completionClaim)await claimPlatformConnectFlow(db,flow);
 const {data,error}=await db.rpc('complete_platform_connect_flow',{
  p_flow:flow.id,p_user:flow.user_id,p_provider:flow.provider,
  p_claim:flow.completionClaim,p_connection:connection
 });
 if(error||data!==true)throw Error(error?.message||'connection_save_failed');
}

import {createClient} from 'npm:@supabase/supabase-js@2.112.4';
const keys=JSON.parse(Deno.env.get('SUPABASE_SECRET_KEYS')||'{}');
const db=createClient(Deno.env.get('SUPABASE_URL')!,keys.default||Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!,{auth:{persistSession:false,autoRefreshToken:false}});
const enc=new TextEncoder(),dec=new TextDecoder(),GQL='https://gql-ps.immomio.com/tenant/graphql';
const unb64=(v:string)=>Uint8Array.from(atob(v),c=>c.charCodeAt(0));
async function secret(n:string){const {data,error}=await db.rpc('get_bot_secret',{secret_name:n});if(error||!data)throw Error('configuration_unavailable');return String(data)}
async function decrypt(row:any){const version=Number(row.key_version)||1,keyRaw=unb64(await secret(`application_credential_key_v${version}`));const key=await crypto.subtle.importKey('raw',keyRaw,{name:'AES-GCM'},false,['decrypt']),aad=enc.encode(`${row.user_id}:immomio:v${version}`);const plain=await crypto.subtle.decrypt({name:'AES-GCM',iv:unb64(row.credential_iv),additionalData:aad},key,unb64(row.credential_ciphertext));return JSON.parse(dec.decode(plain))}
